import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Generative AI -- enumerated source for the Technical Assessment for Generative AI in Azure","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/genai-technical-question-set.md","filePath":"frameworks/genai-technical-question-set.md"}'),o={name:"frameworks/genai-technical-question-set.md"};function n(i,t,s,c,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="generative-ai-enumerated-source-for-the-technical-assessment-for-generative-ai-in-azure" tabindex="-1">Generative AI -- enumerated source for the Technical Assessment for Generative AI in Azure <a class="header-anchor" href="#generative-ai-enumerated-source-for-the-technical-assessment-for-generative-ai-in-azure" aria-label="Permalink to &quot;Generative AI -- enumerated source for the Technical Assessment for Generative AI in Azure&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below -- read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>genai.technical.yaml</code> scores the review in Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/443670b4-11d1-4dd7-8128-b2bdb7a2bf2f/" target="_blank" rel="noreferrer">Technical Assessment for Generative AI in Azure</a>, which checks a team&#39;s readiness to develop, run and maintain Azure AI solutions in production. <code>src/assess/rules/genai.technical.yaml</code> is written against this page only, and every rule cites an item number from the tables below. The design and operating practices are <strong>manual</strong> questions answered with <code>-AssessmentAnswers</code>; the platform configuration Azure data can show is <strong>automated</strong>.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/443670b4-11d1-4dd7-8128-b2bdb7a2bf2f/" target="_blank" rel="noreferrer">Technical Assessment for Generative AI in Azure</a> (question text not published)</td></tr><tr><td>Framework version</td><td>Well-Architected AI workload guidance and Microsoft Foundry guidance on Microsoft Learn, current as of the extraction date (no published version number)</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Each source page below was fetched or searched with the Microsoft Learn MCP tools (<code>microsoft_docs_fetch</code>, <code>microsoft_docs_search</code>) on 2026-11-25. Every property an automated item reads was checked against the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published, so the items below are <strong>Scout-derived</strong>: Scout&#39;s reading of the Well-Architected AI workload guidance and the Microsoft Foundry guidance, grouped into eight readiness areas of Scout&#39;s own. The <code>GENAI-*</code> IDs are Scout&#39;s. The area grouping is Scout&#39;s judgement, not Microsoft&#39;s. This page overlaps <a href="./waf-ai-workload-checklist.html">waf-ai-workload-checklist.md</a> on purpose: that page reviews a workload against design areas, this one asks whether the team and platform are ready for production.</p><p>Sources:</p><ul><li>[WAFO] <a href="https://learn.microsoft.com/azure/well-architected/ai/mlops-genaiops" target="_blank" rel="noreferrer">MLOps and GenAIOps for AI workloads on Azure (WAF AI workload)</a></li><li>[OPS] <a href="https://learn.microsoft.com/azure/well-architected/ai/operations" target="_blank" rel="noreferrer">AI workload operations on Azure (WAF AI workload)</a></li><li>[RAIP] <a href="https://learn.microsoft.com/azure/well-architected/ai/responsible-ai" target="_blank" rel="noreferrer">Responsible AI in Azure workloads (WAF AI workload)</a></li><li>[GAO] <a href="https://learn.microsoft.com/azure/architecture/ai-ml/guide/genaiops-for-mlops" target="_blank" rel="noreferrer">Generative AI operations for organizations with MLOps investments</a></li><li>[BSL] <a href="https://learn.microsoft.com/azure/architecture/ai-ml/architecture/baseline-microsoft-foundry-chat" target="_blank" rel="noreferrer">Baseline Microsoft Foundry chat reference architecture</a></li><li>[FND] <a href="https://learn.microsoft.com/azure/foundry/concepts/architecture" target="_blank" rel="noreferrer">Microsoft Foundry architecture</a></li><li>[NIS] <a href="https://learn.microsoft.com/azure/foundry/how-to/configure-private-link" target="_blank" rel="noreferrer">How to configure network isolation for Microsoft Foundry</a></li><li>[SECB] <a href="https://learn.microsoft.com/security/benchmark/azure/baselines/azure-ai-foundry-security-baseline" target="_blank" rel="noreferrer">Azure security baseline for Microsoft Foundry</a></li><li>[GOVP] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/platform/governance" target="_blank" rel="noreferrer">Govern Azure platform services (PaaS) for AI</a></li><li>[GOVI] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/infrastructure/governance" target="_blank" rel="noreferrer">Governance for AI on Azure infrastructure</a></li><li>[SECP] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/platform/security" target="_blank" rel="noreferrer">Secure Azure platform services (PaaS) for AI</a></li><li>[SEC] <a href="https://learn.microsoft.com/azure/cloud-adoption-framework/ai/secure" target="_blank" rel="noreferrer">Guidance to set up your organization&#39;s AI security process</a></li></ul><p>Automated items are <strong>gated</strong>: they run only when the resources they judge exist, so an estate without them reports those items Not assessed rather than passed or failed. Manual items are answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>); where collected Azure data bears on the question it is attached to the item as evidence.</p><h2 id="the-enumeration-50-items-across-8-readiness-areas" tabindex="-1">The enumeration -- 50 items across 8 readiness areas <a class="header-anchor" href="#the-enumeration-50-items-across-8-readiness-areas" aria-label="Permalink to &quot;The enumeration -- 50 items across 8 readiness areas&quot;">​</a></h2><h3 id="team-skills-and-delivery-ts-5-items" tabindex="-1">Team skills and delivery (TS) -- 5 items <a class="header-anchor" href="#team-skills-and-delivery-ts-5-items" aria-label="Permalink to &quot;Team skills and delivery (TS) -- 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-TS-01</td><td>The team has the skills to build and run generative AI solutions</td><td>Manual</td><td>WAFO, GAO</td></tr><tr><td>GENAI-TS-02</td><td>Use cases are validated with a proof of value before production build</td><td>Manual</td><td>WAFO</td></tr><tr><td>GENAI-TS-03</td><td>The team understands model quotas, limits and regional availability</td><td>Manual</td><td>FND, GOVP</td></tr><tr><td>GENAI-TS-04</td><td>Data scientists review experiments with prompts and retrieval</td><td>Manual</td><td>GAO</td></tr><tr><td>GENAI-TS-05</td><td>Runbooks exist for routine, unplanned and emergency AI operations</td><td>Manual</td><td>WAFO</td></tr></tbody></table><h3 id="solution-design-sd-8-items" tabindex="-1">Solution design (SD) -- 8 items <a class="header-anchor" href="#solution-design-sd-8-items" aria-label="Permalink to &quot;Solution design (SD) -- 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-SD-01</td><td>Models are selected by evaluating candidates against requirements</td><td>Manual</td><td>GAO, FND</td></tr><tr><td>GENAI-SD-02</td><td>The technical pattern (prompting, retrieval-augmented generation or fine-tuning) is chosen with a rationale</td><td>Manual</td><td>GAO</td></tr><tr><td>GENAI-SD-03</td><td>The orchestration layer is separated from the model and the data stores</td><td>Manual</td><td>GAO, BSL</td></tr><tr><td>GENAI-SD-04</td><td>Agent tools and permissions are scoped to each agent&#39;s task</td><td>Manual</td><td>SECP, BSL</td></tr><tr><td>GENAI-SD-05</td><td>A gateway sits in front of model endpoints</td><td>Manual -- <code>domains.integration.apiManagement</code> attached as evidence</td><td>GAO</td></tr><tr><td>GENAI-SD-06</td><td>Related AI resources are deployed in the same region</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>WAFO</td></tr><tr><td>GENAI-SD-07</td><td>Managed platforms are preferred over custom hosting</td><td>Manual -- <code>domains.ai.mlWorkspaces</code> attached as evidence</td><td>GAO</td></tr><tr><td>GENAI-SD-08</td><td>The model deployment type matches residency and throughput needs</td><td>Manual</td><td>FND</td></tr></tbody></table><h3 id="grounding-data-and-search-dg-6-items" tabindex="-1">Grounding data and search (DG) -- 6 items <a class="header-anchor" href="#grounding-data-and-search-dg-6-items" aria-label="Permalink to &quot;Grounding data and search (DG) -- 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-DG-01</td><td>Grounding data sources are selected and prepared deliberately</td><td>Manual</td><td>GAO, WAFO</td></tr><tr><td>GENAI-DG-02</td><td>Search indexes are kept fresh and can be rebuilt</td><td>Manual -- <code>domains.ai.searchServices</code> attached as evidence</td><td>GAO</td></tr><tr><td>GENAI-DG-03</td><td>AI Search services are not on the free tier and have at least two replicas</td><td>Automated -- <code>domains.ai.searchServices</code></td><td>WAFO</td></tr><tr><td>GENAI-DG-04</td><td>AI Search services do not accept API keys</td><td>Automated -- <code>domains.ai.searchServices</code></td><td>SECP</td></tr><tr><td>GENAI-DG-05</td><td>AI Search services have public network access disabled</td><td>Automated -- <code>domains.ai.searchServices</code></td><td>SECP, NIS</td></tr><tr><td>GENAI-DG-06</td><td>Retrieval respects each user&#39;s access to the underlying data</td><td>Manual</td><td>SECP, BSL</td></tr></tbody></table><h3 id="security-and-identity-se-10-items" tabindex="-1">Security and identity (SE) -- 10 items <a class="header-anchor" href="#security-and-identity-se-10-items" aria-label="Permalink to &quot;Security and identity (SE) -- 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-SE-01</td><td>Azure AI accounts do not accept API keys</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>SECP</td></tr><tr><td>GENAI-SE-02</td><td>Azure AI accounts have a managed identity</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>SECP, BSL</td></tr><tr><td>GENAI-SE-03</td><td>Azure AI accounts have public network access disabled</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>NIS, SECB</td></tr><tr><td>GENAI-SE-04</td><td>Azure AI accounts have a private endpoint</td><td>Automated -- <code>domains.ai.cognitiveAccounts</code></td><td>NIS, SECB</td></tr><tr><td>GENAI-SE-05</td><td>Machine learning workspaces have public network access disabled</td><td>Automated -- <code>domains.ai.mlWorkspaces</code></td><td>NIS</td></tr><tr><td>GENAI-SE-06</td><td>Machine learning workspaces use managed network isolation</td><td>Automated -- <code>domains.ai.mlWorkspaces</code></td><td>NIS, FND</td></tr><tr><td>GENAI-SE-07</td><td>Defender for Cloud threat protection for AI services is enabled</td><td>Automated -- <code>security.defenderPlans</code></td><td>GOVP</td></tr><tr><td>GENAI-SE-08</td><td>Customer-managed keys protect data where policy requires them</td><td>Manual -- <code>domains.ai.cognitiveAccounts</code> attached as evidence</td><td>SECP</td></tr><tr><td>GENAI-SE-09</td><td>The threat model covers prompt injection, data leakage, data poisoning and wallet abuse</td><td>Manual</td><td>SEC</td></tr><tr><td>GENAI-SE-10</td><td>Access to AI resources is least privilege, with separate identities per environment</td><td>Manual</td><td>GOVP, GOVI</td></tr></tbody></table><h3 id="responsible-ai-and-content-safety-ra-6-items" tabindex="-1">Responsible AI and content safety (RA) -- 6 items <a class="header-anchor" href="#responsible-ai-and-content-safety-ra-6-items" aria-label="Permalink to &quot;Responsible AI and content safety (RA) -- 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-RA-01</td><td>A content filter policy is bound to every model deployment</td><td>Manual</td><td>FND, BSL</td></tr><tr><td>GENAI-RA-02</td><td>Prompt injection and jailbreak protection is enabled</td><td>Manual</td><td>FND, SEC</td></tr><tr><td>GENAI-RA-03</td><td>A Responsible AI impact assessment is complete</td><td>Manual</td><td>WAFO, RAIP</td></tr><tr><td>GENAI-RA-04</td><td>Adversarial testing is done before release</td><td>Manual</td><td>SEC</td></tr><tr><td>GENAI-RA-05</td><td>Human oversight and user transparency are designed in</td><td>Manual</td><td>RAIP</td></tr><tr><td>GENAI-RA-06</td><td>Interactions are auditable and sensitive data in them is visible</td><td>Manual -- <code>domains.analytics.purviewAccounts</code> attached as evidence</td><td>BSL</td></tr></tbody></table><h3 id="reliability-and-capacity-rc-5-items" tabindex="-1">Reliability and capacity (RC) -- 5 items <a class="header-anchor" href="#reliability-and-capacity-rc-5-items" aria-label="Permalink to &quot;Reliability and capacity (RC) -- 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-RC-01</td><td>Throttling and quota errors are handled</td><td>Manual</td><td>GAO, GOVP</td></tr><tr><td>GENAI-RC-02</td><td>Production capacity is planned, with provisioned throughput where demand is steady</td><td>Manual</td><td>GOVP, FND</td></tr><tr><td>GENAI-RC-03</td><td>Disaster recovery covers model endpoints, indexes and orchestration</td><td>Manual</td><td>GOVP</td></tr><tr><td>GENAI-RC-04</td><td>Model retirement dates are tracked and replacement is tested ahead of time</td><td>Manual</td><td>GOVP</td></tr><tr><td>GENAI-RC-05</td><td>Reliability targets are defined for each AI component</td><td>Manual</td><td>WAFO</td></tr></tbody></table><h3 id="operations-and-monitoring-op-6-items" tabindex="-1">Operations and monitoring (OP) -- 6 items <a class="header-anchor" href="#operations-and-monitoring-op-6-items" aria-label="Permalink to &quot;Operations and monitoring (OP) -- 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-OP-01</td><td>Diagnostic logs from AI resources go to a central workspace</td><td>Manual -- <code>opsPosture.diagnosticCoverage</code> attached as evidence</td><td>OPS, FND</td></tr><tr><td>GENAI-OP-02</td><td>Latency, token usage, throttling and output quality are monitored</td><td>Manual</td><td>OPS, GAO</td></tr><tr><td>GENAI-OP-03</td><td>Alerts exist for AI service health and quality</td><td>Manual -- <code>monitor.metricAlertRules</code> attached as evidence</td><td>GOVP</td></tr><tr><td>GENAI-OP-04</td><td>Evaluation runs in the delivery pipeline and in pre-production</td><td>Manual</td><td>GAO</td></tr><tr><td>GENAI-OP-05</td><td>Quality drift and model decay are monitored in production</td><td>Manual</td><td>GAO, WAFO</td></tr><tr><td>GENAI-OP-06</td><td>Prompts, indexes and orchestration are under source control and deployed as code</td><td>Manual -- <code>management.deployments</code> attached as evidence</td><td>WAFO</td></tr></tbody></table><h3 id="cost-and-performance-co-4-items" tabindex="-1">Cost and performance (CO) -- 4 items <a class="header-anchor" href="#cost-and-performance-co-4-items" aria-label="Permalink to &quot;Cost and performance (CO) -- 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>GENAI-CO-01</td><td>Models are matched to the task, with smaller models for simple work</td><td>Manual</td><td>GOVP</td></tr><tr><td>GENAI-CO-02</td><td>Token use is controlled</td><td>Manual</td><td>GOVP</td></tr><tr><td>GENAI-CO-03</td><td>Cost is tracked per workload against a budget</td><td>Manual -- <code>governance.budgets</code> attached as evidence</td><td>GOVP</td></tr><tr><td>GENAI-CO-04</td><td>Performance benchmarks are set through experimentation</td><td>Manual</td><td>WAFO</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Team skills and delivery</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Solution design</td><td>8</td><td>0</td><td>8</td></tr><tr><td>Grounding data and search</td><td>6</td><td>3</td><td>3</td></tr><tr><td>Security and identity</td><td>10</td><td>7</td><td>3</td></tr><tr><td>Responsible AI and content safety</td><td>6</td><td>0</td><td>6</td></tr><tr><td>Reliability and capacity</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Operations and monitoring</td><td>6</td><td>0</td><td>6</td></tr><tr><td>Cost and performance</td><td>4</td><td>0</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>50</strong></td><td><strong>10</strong></td><td><strong>40</strong></td></tr></tbody></table><p>The AI Search, Azure AI account and machine learning workspace items read the same collected properties as the Well-Architected AI workload review; an estate scored under both sees the same underlying finding twice, under two different ids.</p>',30)])])}const A=e(o,[["render",n]]);export{m as __pageData,A as default};
